/**
 * @file railway-libraries.ts
 * @brief The railway draw.io libraries shown after ERTMS in the Shapes tab: "ERTMS/ETCS extra",
 *        "Polish signalling (PKP PLK)" and "Track layout" (public/libraries/*.xml, generated by
 *        scripts/railway-libraries/build_railway_libraries.py; original work of this repository).
 *
 * Each is a lazy palette source: the file is fetched and parsed (engine parseMxLibrary +
 * libraryToPaletteDef) only when the section is opened or searched. Entries carry their railway
 * data (`rdKind`, ...) in the cells; IDs are generated on insert (prepareRailwayInsert).
 */
import { getDrawioPaletteEngine, libraryToPaletteDef } from './drawio-palette';
import type { LazyPaletteSource } from './drawio-palette';
import { withShortCaption } from './palette-captions';

export interface RailwayLibraryInfo {
  id: string;
  title: string;
  file: string;
  tags: string;
}

/** Palette order in the Shapes tab (after ERTMS). */
export const RAILWAY_LIBRARIES: readonly RailwayLibraryInfo[] = [
  { id: 'etcs-extra', title: 'ERTMS/ETCS extra', file: 'libraries/ertms-extra.xml', tags: 'ertms etcs railway kolej' },
  { id: 'rail-pl', title: 'Polish signalling (PKP PLK)', file: 'libraries/railway-pl.xml', tags: 'pkp plk polska kolej railway' },
  { id: 'track-layout', title: 'Track layout', file: 'libraries/track-layout.xml', tags: 'track layout tor układ torowy railway' },
];

function fileUrl(baseUrl: string, file: string): string {
  return `${baseUrl.endsWith('/') ? baseUrl : `${baseUrl}/`}${file}`;
}

/** Lazy palette sources of the railway libraries, served under `baseUrl`. */
export function railwayLibrarySources(baseUrl: string = import.meta.env.BASE_URL): LazyPaletteSource[] {
  return RAILWAY_LIBRARIES.map((lib) => ({
    id: lib.id,
    title: lib.title,
    defaultVisible: true,
    async load() {
      const url = fileUrl(baseUrl, lib.file);
      const response = await fetch(url);
      if (!response.ok) throw new Error(`HTTP ${response.status} loading ${url}`);
      const entries = getDrawioPaletteEngine().parseMxLibrary(await response.text());
      const def = libraryToPaletteDef(entries, { id: lib.id, title: lib.title, tags: lib.tags, source: lib.file });
      // tile captions keep the distinguishing part of long titles ("1:9 R toe L")
      return { ...def, entries: def.entries.map(withShortCaption) };
    },
  }));
}
